CUDA_CU_SRC = r"""
# <<<IMPROVE:cuda_cu>>>
#include <torch/extension.h>
#include <cuda_runtime.h>

#define BLOCK_SIZE 256

// Output-stationary gather kernel: each thread writes exactly one output element.
// Weight layout matches nn.ConvTranspose1d: [C_in, C_out, K]
__global__ void conv_transpose1d_kernel(
    const float* __restrict__ input,   // [N, C_in, L_in]
    const float* __restrict__ weight,  // [C_in, C_out, K]
    const float* __restrict__ bias,    // [C_out] or nullptr
    float* __restrict__ output,        // [N, C_out, L_out]
    int N, int C_in, int C_out, int L_in, int L_out,
    int K, int stride, int padding, int dilation
) {
    int out_pos = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int oc      = (int)(blockIdx.y % C_out);
    int n= (int)(blockIdx.y / C_out);

    if (out_pos >= L_out || n >= N) return;

    float acc = (bias != nullptr) ? bias[oc] : 0.0f;

    // Gather: for each kernel tap k, check if it maps to a valid input position.
    #pragma unroll 4
    for (int k = 0; k < K; k++) {
        int tmp = out_pos + padding - k * dilation;
        if (tmp < 0) continue;
        if (tmp % stride != 0) continue;
        int in_pos = tmp / stride;
        if (in_pos >= L_in) continue;

        // Accumulate across all input channels.
        const float* w_col = weight + oc * K + k;  // weight[ic, oc, k] = weight[ic*C_out*K + oc*K + k]
        const float* x_col = input  + n * C_in * L_in + in_pos;
        #pragma unroll 8
        for (int ic = 0; ic < C_in; ic++) {
            acc += x_col[ic * L_in] * w_col[ic * C_out * K];
        }
    }

    output[n * C_out * L_out + oc * L_out + out_pos] = acc;
}

torch::Tensor conv_transpose1d_forward_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::optional<torch::Tensor> bias,
    int64_t stride, int64_t padding, int64_t dilation)
{
    const int N    = (int)input.size(0);
    const int C_in = (int)input.size(1);
    const int L_in = (int)input.size(2);
    const int C_out = (int)weight.size(1);
    const int K     = (int)weight.size(2);

    const int L_out = (int)((L_in - 1) * stride - 2 * padding + dilation * (K - 1) + 1);

    auto output = torch::empty({N, C_out, L_out}, input.options());

    const float* bias_ptr = nullptr;
    torch::Tensor bias_contig;
    if (bias.has_value() && bias.value().defined()) {
        bias_contig = bias.value().contiguous();
        bias_ptr = bias_contig.data_ptr<float>();
    }

    dim3 block(BLOCK_SIZE);
    dim3 grid((L_out + BLOCK_SIZE - 1) / BLOCK_SIZE, N * C_out);

    conv_transpose1d_kernel<<<grid, block>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, C_out, L_in, L_out,
        K, (int)stride, (int)padding, (int)dilation
    );

    return output;
}
# <<<END_IMPROVE>>>
