#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <ATen/cuda/CUDAContext.h>

// Output-stationary gather kernel.
// Weight layout: [C_in, C_out, K]  (matches nn.ConvTranspose1d)
// Input  layout: [N, C_in, L_in]
// Output layout: [N, C_out, L_out]
//
// For each output element (n, oc, o):
//   out[n,oc,o] = bias[oc] + sum_{ic,k} weight[ic,oc,k] * input[n,ic,(o+padding-k*dilation)/stride]
//                            where (o+padding-k*dilation) >= 0
//                              and (o+padding-k*dilation) % stride == 0
//                              and (o+padding-k*dilation)/stride < L_in

// ---- Generic kernel -------------------------------------------------------
__global__ void conv_transpose1d_kernel_generic(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float*       __restrict__ output,
    int N, int C_in, int C_out, int L_in, int L_out,
    int K, int stride, int padding, int dilation
) {
    int o  = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int oc = (int)(blockIdx.y);
    int n  = (int)(blockIdx.z);

    if (o >= L_out) return;

    float acc = (bias != nullptr) ? bias[oc] : 0.0f;

    for (int k = 0; k < K; k++) {
        int tmp = o + padding - k * dilation;
        if (tmp < 0) continue;
        if (tmp % stride != 0) continue;
        int in_pos = tmp / stride;
        if (in_pos >= L_in) continue;
        // weight[ic, oc, k]
        for (int ic = 0; ic < C_in; ic++) {
            acc += input[n * C_in * L_in + ic * L_in + in_pos]
                 * weight[ic * C_out * K + oc * K + k];
        }
    }

    output[n * C_out * L_out + oc * L_out + o] = acc;
}

// ---- Specialised kernel: K=3, stride=2, padding=1, dilation=2 -------------
//  Valid (tmp, in_pos) per tap:
//    k=0: tmp = o+1,       accept if (o+1) even  => in_pos = (o+1)/2
//    k=1: tmp = o+1-2 = o-1, accept if (o-1) even and >=0 => in_pos = (o-1)/2
//    k=2: tmp = o+1-4 = o-3, accept if (o-3) even and >=0 => in_pos = (o-3)/2
__global__ void conv_transpose1d_kernel_k3s2p1d2(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float*       __restrict__ output,
    int N, int C_in, int C_out, int L_in, int L_out
) {
    int o  = (int)(blockIdx.x * blockDim.x + threadIdx.x);
    int oc = (int)(blockIdx.y);
    int n  = (int)(blockIdx.z);

    if (o >= L_out) return;

    float acc = (bias != nullptr) ? bias[oc] : 0.0f;

    // Precompute valid taps
    int tmp0 = o + 1;       // k=0: padding=1, k*dilation=0
    int tmp1 = o - 1;       // k=1: padding=1, k*dilation=2
    int tmp2 = o - 3;       // k=2: padding=1, k*dilation=4

    bool v0 = (tmp0 >= 0) && ((tmp0 & 1) == 0);
    bool v1 = (tmp1 >= 0) && ((tmp1 & 1) == 0);
    bool v2 = (tmp2 >= 0) && ((tmp2 & 1) == 0);

    int ip0 = v0 ? (tmp0 >> 1) : 0;
    int ip1 = v1 ? (tmp1 >> 1) : 0;
    int ip2 = v2 ? (tmp2 >> 1) : 0;

    bool ov0 = v0 && (ip0 < L_in);
    bool ov1 = v1 && (ip1 < L_in);
    bool ov2 = v2 && (ip2 < L_in);

