    const float* w_oc  = weight + oc;            // weight[ic, oc, k] offset for oc
    // weight stride: C_out*K per ic, K per oc-step handled by indexing
    // weight[ic,oc,k] = weight_base[ ic*C_out*3 + oc*3 + k ]

    int C_out3 = C_out * 3;

    for (int ic = 0; ic < C_in; ic++) {
        const float* inp_ic = inp_n + ic * L_in;
        const float* w_ic   = weight + ic * C_out3 + oc * 3;

        if (ov0) acc += inp_ic[ip0] * w_ic[0];
        if (ov1) acc += inp_ic[ip1] * w_ic[1];
        if (ov2) acc += inp_ic[ip2] * w_ic[2];
    }

